class Stapel<T>
{
    private readonly List<T> _daten
        = new();
    public void Push(T wert)
        => _daten.Add(wert);
    public T Pop()
    {
        T w = _daten[^1];
        _daten.RemoveAt(_daten.Count - 1);
        return w;
    }
    public int Anzahl => _daten.Count;
}

var s = new Stapel<int>();
s.Push(1);
s.Push(2);
Console.WriteLine(s.Pop());   // 2
Console.WriteLine(s.Anzahl);  // 1

static void Tausche<T>(ref T a,
                       ref T b)
{
    T tmp = a;
    a = b;
    b = tmp;
}

int x = 1, y = 2;
Tausche(ref x, ref y); // T = int
Console.WriteLine($"{x} {y}"); // 2 1

static T Groesstes<T>(T[] werte)
    where T : IComparable<T>
{
    T max = werte[0];
    foreach (T w in werte)
        if (w.CompareTo(max) > 0)
            max = w;
    return max;
}

Console.WriteLine(
    Groesstes(new[] { 3, 9, 4 }));
// 9
Console.WriteLine(Groesstes(
    new[] { "Birne", "Apfel" }));
// Birne (alphabetisch größer)

interface IHatId { int Id { get; set; } }

class Lager<T> where T : class, IHatId
{
    private readonly List<T> _items = new();
    private int _naechste = 1;
    public void Add(T item)
    {
        item.Id = _naechste++; // IHatId!
        _items.Add(item);
    }
    public T? Suche(int id) =>
        _items.Find(i => i.Id == id);
}

